INSERT INTO public.photos VALUES ('53b3f4fe-59f5-4ba2-9a25-6e455da8376f', 'Flora', 'https://uploads7.wikiart.org/00180/images/rembrandt/flora.jpg', 'eeb73610-ea2e-4934-a2cc-3e1f9b9cda72', 5000, 6160, '2026-05-03 22:47:55.069561', '2026-05-03 22:47:55.069564', 'Rembrandt painted his wife Saskia van Uylenburgh as Flora, goddess of spring and flowers, three times: in 1634,1635 and 1641. In this work he combined elements of pastoral and historical portraits. Created in the year of their marriage, this painting shows the love and admiration the artist felt for the young woman. The contrast between the young sitter''s diffident pose and the sumptuousness of her richly embroidered clothes and accessories gives the image a special charm.', '1634', 'Baroque', 'Hermitage Museum, Saint Petersburg, Russia', '', 'oil, canvas', '', false);
