INSERT INTO public.photos VALUES ('625fd470-b58b-478e-8217-6f457b12c91f', 'Imaginary View of the Grand Gallery of the Louvre in Ruins', 'https://uploads2.wikiart.org/images/hubert-robert/imaginary-view-of-the-grand-gallery-of-the-louvre-in-ruins-1796.jpg', '535481e1-4b8e-40c3-a27e-c6f0c107cd18', 1280, 984, '2026-05-03 22:47:55.102538', '2026-05-03 22:47:55.10254', '', '1796', 'Rococo', 'Louvre, Paris, France', '', '', '', false);
INSERT INTO public.photos VALUES ('c543dd20-ac11-4efa-a426-7df33f2332f2', 'The Starry Night', 'https://uploads3.wikiart.org/00142/images/vincent-van-gogh/the-starry-night.jpg', 'f3180431-a034-4a4f-9f74-e1c151ac79a8', 5000, 3959, '2026-05-03 22:47:55.108252', '2026-05-03 22:47:55.108254', 'Van Gogh''s night sky is a field of roiling energy. Below the exploding stars, the village is a place of quiet order. Connecting earth and sky is the flamelike cypress, a tree traditionally associated with graveyards and mourning. But death was not ominous for van Gogh. "Looking at the stars always makes me dream," he said, "Why, I ask myself, shouldn''t the shining dots of the sky be as accessible as the black dots on the map of France? Just as we take the train to get to Tarascon or Rouen, we take death to reach a star."
INSERT INTO public.photos VALUES ('85b7de39-4135-40bb-bc4d-a69d96dbe5c1', 'Under the bridge at Hampton Court', 'https://uploads4.wikiart.org/images/alfred-sisley/under-the-bridge-at-hampton-court-1874.jpg', 'f48b805d-99bd-4315-aabf-3b0dcf18b4ee', 3912, 2604, '2026-05-03 22:47:55.113534', '2026-05-03 22:47:55.113538', '', '1874', 'Impressionism', 'Kunstmuseum Winterthur, Winterthur, Switzerland', '', 'oil, canvas', '', false);
INSERT INTO public.photos VALUES ('5a1fdb71-dc47-4cf9-9faf-246f9ed7d71b', 'Christ in the Storm', 'https://uploads8.wikiart.org/00142/images/rembrandt/christ-in-the-storm.jpg', 'eeb73610-ea2e-4934-a2cc-3e1f9b9cda72', 1930, 2400, '2026-05-03 22:47:55.055845', '2026-05-03 23:48:46.822023', 'The best known work by Rembrandt, this painting resides at the State Museum in Amsterdam, where it is lauded as one of the most famous paintings in the world. For much of its history, the painting was covered with a thick layer of varnish, giving the impression that it was a night scene, hence the name. The varnish was removed in 1940, revealing the bright colors of the painting. The painting has also suffered damage at the hand of art dealers, who in 1715 cut the painting down on three side on order to fit it between two columns, and vandals, who have purposely tried to ruin the painting. In 1975, an unemployed school teacher attacked the work, leaving a large section of zig-zags scratches. The painting was successfully restored, although the scratches are still somewhat visible. In 1990, the painting was attacked again, by a man who threw acid on the canvas. The acid was quickly neutralized, however, and the painting was saved.', '1633', 'Baroque', 'Isabella Stewart Gardner Museum (Fenway Court), Boston, MA, US', '', 'oil, board, canvas', '', true);
