INSERT INTO public.photos VALUES ('53ee93fd-9f7a-4074-93f0-389bdc363ace', 'A Witches'' Sabbath', 'https://www.artic.edu/iiif/2/8cd4328f-da34-dec3-00f5-5810a747c8e8/full/1686,/0/default.jpg', 'd2eb6e18-efc0-4dae-b401-e4d12b454578', 1920, 1080, '2026-05-04 22:41:49.463224', '2026-05-04 22:41:49.463224', 'JEOPARDY KEY: "A Witches'' Sabbath" by Cornelis Saftleven. Artist: Cornelis Saftleven (Dutch, 1607–1681). Date: c. 1650. Medium: Oil on panel. Style/Period: dutch. Cultural origin: Holland. Currently housed at: Art Institute of Chicago.', 'c. 1650', 'dutch', 'Art Institute of Chicago', '54.3 × 78.2 cm (21 3/8 × 30 3/4 in.); Framed: 77.1 × 101.6 × 10.2 cm (30 3/8 × 40 × 4 in.)', 'Oil on panel', 'Art Institute of Chicago', false);
INSERT INTO public.photos VALUES ('23045158-c2e2-42a2-8cf9-46d5102442bf', 'Sandvika, Norway', 'https://www.artic.edu/iiif/2/07d8dd31-d44b-85aa-ab09-ca51ee86f631/full/1686,/0/default.jpg', 'b9b15084-185a-4aa9-98b0-f8f320541e5a', 1920, 1080, '2026-05-04 22:41:49.467569', '2026-05-04 22:41:49.467569', 'JEOPARDY KEY: "Sandvika, Norway" by Claude Monet. Artist: Claude Monet (French, 1840–1926). Date: 1895. Medium: Oil on canvas. Style/Period: Impressionism. Cultural origin: France. Currently housed at: Art Institute of Chicago.', '1895', 'Impressionism', 'Art Institute of Chicago', '73.4 × 92.5 cm (28 7/8 × 36 3/8 in.); Framed: 98.8 × 118.2 × 11.2 cm (38 7/8 × 46 1/2 × 4 3/8 in.)', 'Oil on canvas', 'Art Institute of Chicago', false);
INSERT INTO public.photos VALUES ('0041080d-e125-4e22-9fb8-05ef98b3eade', 'Portrait of a Man with Gray Hair', 'https://www.artic.edu/iiif/2/51a56e7e-ffa2-bb9e-7f16-99bc0b4b4d66/full/1686,/0/default.jpg', '15c20012-cad3-4cb4-b424-5a3651157705', 1920, 1080, '2026-05-04 22:41:49.476086', '2026-05-04 22:41:49.476086', 'JEOPARDY KEY: "Portrait of a Man with Gray Hair" by Sir Henry Raeburn. Artist: Henry Raeburn (Scottish, 1756–1823). Date: 1810–20. Medium: Oil on canvas. Style/Period: nineteenth century. Cultural origin: Scotland. Currently housed at: Art Institute of Chicago.', '1810–20', 'nineteenth century', 'Art Institute of Chicago', '73.6 × 62.8 cm (29 × 24 3/4 in.); Framed: 96.6 × 84.5 × 8.3 cm (38 × 33 1/4 × 3 1/4 in.)', 'Oil on canvas', 'Art Institute of Chicago', false);
INSERT INTO public.photos VALUES ('0a3923ae-4ca7-4290-b4d6-8a1c30d1b97f', 'The Advance-Guard, or The Military Sacrifice (The Ambush)', 'https://www.artic.edu/iiif/2/f1e03813-f9c7-f4f8-fbe8-a5eeae84fda4/full/1686,/0/default.jpg', '8f772b2a-7750-460f-bff4-83ce4f54de3e', 1920, 1080, '2026-05-04 22:41:49.48557', '2026-05-04 22:41:49.48557', 'JEOPARDY KEY: "The Advance-Guard, or The Military Sacrifice (The Ambush)" by Frederic Remington. Artist: Frederic Remington (American, 1861–1909). Date: 1890. Medium: Oil on canvas. Style/Period: painting. Cultural origin: New York. Currently housed at: Art Institute of Chicago.', '1890', 'painting', 'Art Institute of Chicago', '87.3 × 123.1 cm (34 3/8 × 48 1/2 in.)', 'Oil on canvas', 'Art Institute of Chicago', false);
INSERT INTO public.photos VALUES ('f7b12cb7-6f42-4e75-9491-986f405f86cb', 'Grapes, Lemons, Pears, and Apples', 'https://www.artic.edu/iiif/2/f11bd233-6cc3-4221-59eb-f7363be4119e/full/1686,/0/default.jpg', 'f3180431-a034-4a4f-9f74-e1c151ac79a8', 1920, 1080, '2026-05-04 22:41:49.492094', '2026-05-04 22:41:49.492094', 'JEOPARDY KEY: "Grapes, Lemons, Pears, and Apples" by Vincent van Gogh. Artist: Vincent van Gogh (Dutch, 1853–1890). Date: 1887. Medium: Oil on canvas. Style/Period: Post-Impressionism. Cultural origin: Paris. Currently housed at: Art Institute of Chicago.', '1887', 'Post-Impressionism', 'Art Institute of Chicago', '46.5 × 55.2 cm (18 1/4 × 21 3/4 in.); Framed: 57.8 × 66.7 × 5.1 cm (22 3/4 × 26 1/4 × 2 in.)', 'Oil on canvas', 'Art Institute of Chicago', false);
INSERT INTO public.photos VALUES ('566b3de6-e2f5-41a4-8b15-a433b11f3793', 'Nocturne: Blue and Gold—Southampton Water', 'https://www.artic.edu/iiif/2/50034c7f-ce51-00f1-430e-a6f7efc233fc/full/1686,/0/default.jpg', 'bb252bde-758f-43ca-8d13-51659acda56a', 1920, 1080, '2026-05-04 22:41:49.500371', '2026-05-04 22:41:49.500371', 'JEOPARDY KEY: "Nocturne: Blue and Gold—Southampton Water" by James McNeill Whistler. Artist: James McNeill Whistler (American, 1834–1903). Date: 1872. Medium: Oil on canvas. Style/Period: Impressionism. Cultural origin: London. Currently housed at: Art Institute of Chicago.', '1872', 'Impressionism', 'Art Institute of Chicago', '51 × 76.7 cm (20 1/16 × 30 3/16 in.)', 'Oil on canvas', 'Art Institute of Chicago', false);
INSERT INTO public.photos VALUES ('38a2c737-5020-4355-bfa0-6b1cf433b453', 'Moulin de la Galette', 'https://www.artic.edu/iiif/2/156aaed6-fe3c-a13c-f39e-55f381205929/full/1686,/0/default.jpg', '1379faaf-e203-4b2a-91cb-676f98584958', 1920, 1080, '2026-05-04 22:41:49.506141', '2026-05-04 22:41:49.506141', 'JEOPARDY KEY: "Moulin de la Galette" by Henri de Toulouse-Lautrec. Artist: Henri de Toulouse-Lautrec (French, 1864–1901). Date: 1889. Medium: Oil on canvas. Style/Period: Post-Impressionism. Cultural origin: France. Currently housed at: Art Institute of Chicago.', '1889', 'Post-Impressionism', 'Art Institute of Chicago', '88.5 × 101.3 cm (35 7/8 × 39 5/8 in.); Framed: 109.3 × 123.2 × 12.1 cm (43 × 48 1/2 × 4 3/4 in.)', 'Oil on canvas', 'Art Institute of Chicago', false);
INSERT INTO public.photos VALUES ('0ec21414-7f4f-40df-a108-06ecc897aac1', 'The Eruption of Vesuvius', 'https://www.artic.edu/iiif/2/6a676ee7-39c0-0b88-c37e-36ba0c5e3065/full/1686,/0/default.jpg', '5d3c4d0a-d7db-46ac-b96f-bb6c83eef89c', 1920, 1080, '2026-05-04 22:41:49.515026', '2026-05-04 22:41:49.515026', 'JEOPARDY KEY: "The Eruption of Vesuvius" by Pierre-Jacques Volaire. Artist: Pierre-Jacques Volaire (French, 1729–1799). Date: 1771. Medium: Oil on canvas. Style/Period: 18th Century. Cultural origin: France. Currently housed at: Art Institute of Chicago.', '1771', '18th Century', 'Art Institute of Chicago', '116.8 × 242.9 cm (46 × 95 5/8 in.)', 'Oil on canvas', 'Art Institute of Chicago', false);
INSERT INTO public.photos VALUES ('e1a4a0cc-885d-4f66-967d-7ddbea1e12b1', 'Madame Roulin Rocking the Cradle (La berceuse)', 'https://www.artic.edu/iiif/2/6f3ca8b9-fef6-edfc-a71c-3e7b471d5f6c/full/1686,/0/default.jpg', 'f3180431-a034-4a4f-9f74-e1c151ac79a8', 1920, 1080, '2026-05-04 22:41:49.520288', '2026-05-04 22:41:49.520288', 'JEOPARDY KEY: "Madame Roulin Rocking the Cradle (La berceuse)" by Vincent van Gogh. Artist: Vincent van Gogh (Dutch, 1853–1890). Date: 1889. Medium: Oil on canvas. Style/Period: Post-Impressionism. Cultural origin: Netherlands. Currently housed at: Art Institute of Chicago.', '1889', 'Post-Impressionism', 'Art Institute of Chicago', '92.7 × 73.8 cm (36 1/2 × 29 1/2 in.); Framed: 111.9 × 91.8 × 8.3 cm (44 1/16 × 36 1/8 × 3 1/2 in.)', 'Oil on canvas', 'Art Institute of Chicago', false);
INSERT INTO public.photos VALUES ('067230b8-3e8e-421e-bc9e-430f6de1f04e', 'Les Demoiselles d''Avignon', 'https://upload.wikimedia.org/wikipedia/en/4/4c/Les_Demoiselles_d%27Avignon.jpg', 'ff115354-a442-4412-923b-118cdb1f31ee', 1920, 1080, '2026-05-04 22:41:49.531896', '2026-05-04 22:41:49.531896', 'JEOPARDY KEY: Revolutionary proto-Cubist work showing five nude women composed of flat, angular planes. The two figures on the right have African mask-like faces — Picasso was influenced by Iberian sculpture and African art. This painting shocked even Picasso''s closest friends. Matisse considered it an ''outrage.'' It broke from traditional European painting perspective and is considered a pivotal work leading to Cubism.', '1907', 'Proto-Cubism', 'Museum of Modern Art (MoMA), New York', '243.9 × 233.7 cm', 'Oil on canvas', 'MoMA', false);
INSERT INTO public.photos VALUES ('b76e7fac-7637-453b-87ce-19815f8e208c', 'Christina''s World', 'https://upload.wikimedia.org/wikipedia/en/a/a2/Christina%27s_World.jpg', 'b156cc36-c48b-43c6-8be0-84427fc8660e', 1920, 1080, '2026-05-04 22:41:49.539086', '2026-05-04 22:41:49.539086', 'JEOPARDY KEY: Shows a woman (Christina Olson, who had a degenerative muscular disorder) crawling across a brown field toward a gray farmhouse. Wyeth''s neighbor in Cushing, Maine. Painted in egg tempera, not oil — a tell for Wyeth. The vast emptiness between figure and house creates psychological tension. One of the best-known American paintings of the 20th century.', '1948', 'Realism / Regionalism', 'Museum of Modern Art (MoMA), New York', '81.9 × 121.3 cm', 'Tempera on panel', 'MoMA', false);
INSERT INTO public.photos VALUES ('b9605eb4-4cbc-490f-9b66-7125db8dba99', 'Dempsey and Firpo', 'https://upload.wikimedia.org/wikipedia/commons/7/71/Bellows_George_Dempsey_and_Firpo_1924.jpg', 'eef09113-832f-4b51-b255-e025d16d7224', 1920, 1080, '2026-05-04 22:41:49.549663', '2026-05-04 22:41:49.549663', 'JEOPARDY KEY: Captures the famous moment when Argentine boxer Luis Ángel Firpo knocked Jack Dempsey out of the ring during their 1923 heavyweight title fight. Bellows was a leader of the Ashcan School — known for gritty, urban American realism. His boxing paintings are his most famous works. Dramatic diagonal composition and dynamic figures are Bellows tells.', '1924', 'Ashcan School', 'Whitney Museum of American Art, New York', '129.5 × 160.6 cm', 'Oil on canvas', 'Whitney', false);
INSERT INTO public.photos VALUES ('f7aef2fc-6cd5-4741-a11d-9e333e66a791', 'Girl with a Pearl Earring', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0f/1665_Girl_with_a_Pearl_Earring.jpg/800px-1665_Girl_with_a_Pearl_Earring.jpg', '2b402aa4-6259-4872-b888-8a173943cc5c', 1920, 1080, '2026-05-04 22:41:49.555502', '2026-05-04 22:41:49.555502', 'JEOPARDY KEY: Called the ''Mona Lisa of the North.'' A tronie (character study), not a portrait of a specific person. The luminous pearl earring is the focal point. Vermeer''s signature tells: exquisite light rendering, ultramarine blue (ground from expensive lapis lazuli), and intimate domestic scale. Only ~34 verified Vermeer paintings exist. The turban suggests exotic/Oriental influence popular in 17th-century Dutch painting.', 'c. 1665', 'Dutch Golden Age / Baroque', 'Mauritshuis, The Hague, Netherlands', '44.5 × 39 cm', 'Oil on canvas', 'Mauritshuis', false);
INSERT INTO public.photos VALUES ('e3a4d095-2fff-4fc0-b45f-405ac276d7fb', 'The Night Watch', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5a/The_Night_Watch_-_HD.jpg/1280px-The_Night_Watch_-_HD.jpg', 'ce8c3715-8552-4938-85e3-f1f110480466', 1920, 1080, '2026-05-04 22:41:49.559599', '2026-05-04 22:41:49.559599', 'JEOPARDY KEY: Actually titled ''Militia Company of District II under Captain Frans Banninck Cocq.'' It''s NOT a night scene — centuries of varnish darkened it. Largest Rembrandt painting. Shows a militia company in dramatic motion rather than the standard static group portrait. Rembrandt tells: dramatic chiaroscuro (extreme light/dark contrast), rich impasto, psychological depth in faces. It was trimmed on all sides when moved in 1715.', '1642', 'Dutch Golden Age / Baroque', 'Rijksmuseum, Amsterdam, Netherlands', '363 × 437 cm', 'Oil on canvas', 'Rijksmuseum', false);
INSERT INTO public.photos VALUES ('c77cb3dc-c35a-4b43-80a1-5e43b624f2e0', 'The Birth of Venus', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0b/Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg/1280px-Sandro_Botticelli_-_La_nascita_di_Venere_-_Google_Art_Project_-_edited.jpg', 'c37f51f9-10c8-41f4-8211-4b387050c949', 1920, 1080, '2026-05-04 22:41:49.566726', '2026-05-04 22:41:49.566726', 'JEOPARDY KEY: Venus emerges from the sea as a full-grown woman on a giant scallop shell. Botticelli tells: elongated figures, flowing golden hair, delicate linear style, mythological subjects. Commissioned by the Medici family. One of the first large-scale Renaissance paintings on canvas (not wood panel). The figure of Venus is based on the ancient Venus de'' Medici sculpture. Painted with tempera, not oil.', 'c. 1485', 'Early Renaissance', 'Uffizi Gallery, Florence, Italy', '172.5 × 278.9 cm', 'Tempera on canvas', 'Uffizi', false);
INSERT INTO public.photos VALUES ('f621b1a1-f1ce-4e06-a20a-b0812bbfb90b', 'Liberty Leading the People', 'https://upload.wikimedia.org/wikipedia/commons/thumb/5/5d/Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg/1280px-Eug%C3%A8ne_Delacroix_-_Le_28_Juillet._La_Libert%C3%A9_guidant_le_peuple.jpg', 'd07130ad-6446-4111-94e2-4da6cde91fdb', 1920, 1080, '2026-05-04 22:41:49.573876', '2026-05-04 22:41:49.573876', 'JEOPARDY KEY: Commemorates the July Revolution of 1830 that toppled King Charles X. The bare-breasted woman is Marianne — allegorical figure of the French Republic and Liberty. She holds the tricolore flag. Delacroix tells: vivid dramatic color, energetic brushwork, Romantic emphasis on emotion over reason. Delacroix included himself in the painting (man in top hat with rifle). Inspired the Statue of Liberty''s design.', '1830', 'Romanticism', 'Louvre Museum, Paris, France', '260 × 325 cm', 'Oil on canvas', 'Louvre', false);
INSERT INTO public.photos VALUES ('96c693fb-bb56-40da-8f04-a3bde8eebf7c', 'The Great Wave off Kanagawa', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/a5/Tsunami_by_hokusai_19th_century.jpg/1280px-Tsunami_by_hokusai_19th_century.jpg', '025f8724-a7a0-42dd-a2f9-39ce5dea74dc', 1920, 1080, '2026-05-04 22:41:49.582786', '2026-05-04 22:41:49.582786', 'JEOPARDY KEY: Part of ''Thirty-six Views of Mount Fuji'' series. Mt. Fuji appears tiny in the background — the wave dominates. NOT a painting but a woodblock print. Hokusai was ~70 when he made this. Used Prussian blue pigment (recently imported from Europe). Three boats with fishermen are caught in the waves. One of the most reproduced images in art history. Influenced Western Impressionists including Monet and Van Gogh.', 'c. 1831', 'Ukiyo-e', 'Metropolitan Museum of Art, New York (and others)', '25.7 × 37.9 cm', 'Woodblock print (nishiki-e); ink and color on paper', 'Multiple collections', false);
INSERT INTO public.photos VALUES ('d7ef490b-7e38-41b0-ab00-af1670e5a99c', 'Wanderer above the Sea of Fog', 'https://upload.wikimedia.org/wikipedia/commons/thumb/b/b9/Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg/800px-Caspar_David_Friedrich_-_Wanderer_above_the_sea_of_fog.jpg', 'baff8021-119a-4720-bcda-c7cd80a4e6e9', 1920, 1080, '2026-05-04 22:41:49.592186', '2026-05-04 22:41:49.592186', 'JEOPARDY KEY: Iconic image of Romanticism. A man in a dark frock coat stands on a rocky precipice, back to viewer, gazing over a sea of fog. Friedrich tells: Rückenfigur (figure seen from behind, inviting viewer to share their perspective), sublime landscapes, tiny humans dwarfed by nature. Friedrich was the leading German Romantic painter. This painting epitomizes the Romantic concept of the Sublime — nature''s overwhelming, awe-inspiring power.', 'c. 1818', 'Romanticism', 'Hamburger Kunsthalle, Hamburg, Germany', '94.8 × 74.8 cm', 'Oil on canvas', 'Hamburger Kunsthalle', false);
INSERT INTO public.photos VALUES ('76c5e130-2212-4bc3-9a0c-32a088e361bd', 'A Bar at the Folies-Bergère', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0d/Edouard_Manet%2C_A_Bar_at_the_Folies-Berg%C3%A8re.jpg/1280px-Edouard_Manet%2C_A_Bar_at_the_Folies-Berg%C3%A8re.jpg', '1ffc18e2-a658-4761-b1cc-69efcf2ddc6d', 1920, 1080, '2026-05-04 22:41:49.598637', '2026-05-04 22:41:49.598637', 'JEOPARDY KEY: Manet''s last major work before his death. A barmaid stands behind a marble counter; behind her, a mirror reflects the crowded concert hall. The mirror reflection is deliberately ''wrong'' — the reflection doesn''t align with the viewer''s perspective. Manet tells: bold brushstrokes, flat areas of color, modern Parisian subjects, dark outlines. He bridged Realism and Impressionism. Notice the still life of bottles, oranges, and flowers on the counter.', '1882', 'Impressionism / Realism', 'Courtauld Gallery, London, UK', '96 × 130 cm', 'Oil on canvas', 'Courtauld Gallery', false);
INSERT INTO public.photos VALUES ('c3e4b685-47ab-45ba-9bbc-70f92e721f70', 'Watson and the Shark', 'https://upload.wikimedia.org/wikipedia/commons/thumb/7/71/Watson_and_the_Shark_%281778%29.jpg/1280px-Watson_and_the_Shark_%281778%29.jpg', '71867d82-a670-4057-936e-83d7975156e0', 1920, 1080, '2026-05-04 22:41:49.60468', '2026-05-04 22:41:49.60468', 'JEOPARDY KEY: Depicts the real rescue of Brook Watson from a shark attack in Havana Harbor in 1749. Watson later became Lord Mayor of London. Copley was the first major American painter — self-taught in Boston. This was his first history painting after moving to London. The Black figure at the top of the rescue composition is one of the most prominent and dignified depictions of a Black person in 18th-century Western art.', '1778', 'Romanticism / History painting', 'National Gallery of Art, Washington, D.C.', '182.1 × 229.7 cm', 'Oil on canvas', 'National Gallery of Art', false);
INSERT INTO public.photos VALUES ('416b7dd9-14a0-4dab-80e7-37569d7802df', 'The Judgment of Paris', 'https://images.metmuseum.org/CRDImages/ep/original/DP280358.jpg', 'a17dde6b-701a-48f1-bd4c-60a8f4058ad7', 1920, 1080, '2026-05-09 17:54:04.094839', '2026-05-09 17:54:04.094839', 'JEOPARDY KEY: "The Judgment of Paris" by Lucas Cranach the Elder. Artist: German, Kronach 1472–1553 Weimar. Date: ca. 1528. Medium: Oil on beech. Style/Period: European Paintings. Currently housed at: Metropolitan Museum of Art, New York, NY.', 'ca. 1528', 'European Paintings', 'Metropolitan Museum of Art, New York, NY', '40 1/8 x 28in. (101.9 x 71.1cm)', 'Oil on beech', 'Met Museum', false);
INSERT INTO public.photos VALUES ('c2448803-aa57-4ae6-a599-e0e93a41bcdc', 'View of Toledo', 'https://images.metmuseum.org/CRDImages/ep/original/DP349564.jpg', 'd5efcf32-a62d-4d7a-a67d-a4a9b9586ec7', 1920, 1080, '2026-05-09 17:54:04.105399', '2026-05-09 17:54:04.105399', 'JEOPARDY KEY: "View of Toledo" by El Greco (Domenikos Theotokopoulos). Artist: Greek, Iráklion (Candia) 1541–1614 Toledo. Date: ca. 1599–1600. Medium: Oil on canvas. Style/Period: European Paintings. Currently housed at: Metropolitan Museum of Art, New York, NY.', 'ca. 1599–1600', 'European Paintings', 'Metropolitan Museum of Art, New York, NY', '47 3/4 x 42 3/4 in. (121.3 x 108.6 cm)', 'Oil on canvas', 'Met Museum', false);
INSERT INTO public.photos VALUES ('3a71b86e-b99a-4f29-87ed-238d1a9c3160', 'Cardinal Fernando Niño de Guevara (1541–1609)', 'https://images.metmuseum.org/CRDImages/ep/original/DP-17777-001.jpg', 'd5efcf32-a62d-4d7a-a67d-a4a9b9586ec7', 1920, 1080, '2026-05-09 17:54:04.10946', '2026-05-09 17:54:04.10946', 'JEOPARDY KEY: "Cardinal Fernando Niño de Guevara (1541–1609)" by El Greco (Domenikos Theotokopoulos). Artist: Greek, Iráklion (Candia) 1541–1614 Toledo. Date: ca. 1600. Medium: Oil on canvas. Style/Period: European Paintings. Currently housed at: Metropolitan Museum of Art, New York, NY.', 'ca. 1600', 'European Paintings', 'Metropolitan Museum of Art, New York, NY', '67 1/4 x 42 1/2in. (170.8 x 108cm)', 'Oil on canvas', 'Met Museum', false);
INSERT INTO public.photos VALUES ('008acb55-0073-4dcc-bdd4-173025af89a4', 'St. Barbara', 'https://images.metmuseum.org/CRDImages/dp/original/DP842115.jpg', 'a17dde6b-701a-48f1-bd4c-60a8f4058ad7', 1920, 1080, '2026-05-30 00:25:54.110902', '2026-05-30 00:25:54.110906', 'JEOPARDY KEY: "St. Barbara" by Lucas Cranach the Elder. Artist: German, Kronach 1472–1553 Weimar. Medium: Woodcut. Currently housed at: Metropolitan Museum of Art, New York, NY.', '', '', 'Metropolitan Museum of Art, New York, NY', 'Sheet: 8 9/16 × 5 1/16 in. (21.7 × 12.8 cm)', 'Woodcut', 'Met Museum Discover', false);
INSERT INTO public.photos VALUES ('97769147-6d5e-4766-b0fd-f4c9960e68ec', 'The Harvesters', 'https://images.metmuseum.org/CRDImages/ep/original/DP119115.jpg', '771270b0-4640-46f9-b931-3fd9c8a596d0', 1920, 1080, '2026-05-09 17:54:04.11469', '2026-05-09 17:54:04.11469', 'JEOPARDY KEY: "The Harvesters" by Pieter Bruegel the Elder. Artist: Netherlandish, Breda (?) ca. 1525–1569 Brussels. Date: 1565. Medium: Oil on wood. Style/Period: European Paintings. Currently housed at: Metropolitan Museum of Art, New York, NY.', '1565', 'European Paintings', 'Metropolitan Museum of Art, New York, NY', 'Overall, including added strips at top, bottom, and right, 46 7/8 x 63 3/4 in. (119 x 162 cm); original painted surface 45 7/8 x 62 7/8 in. (116.5 x 159.5 cm)', 'Oil on wood', 'Met Museum', false);
